func resourceNextCursor(config resourceReadConfig, current, next string, hasMore bool) (string, bool, error) {
	if config.paginationType == "offset" || config.paginationType == "page" {
		return current, false, nil
	}
	if next == "" {
		if hasMore {
			return "", false, fmt.Errorf("pagination reports more pages without an advanceable cursor")
		}
		return "", true, nil
	}
	if next == current {
		return "", false, fmt.Errorf("pagination cursor %q did not advance", current)
	}
	return next, false, nil
}
